function dutyGrid(){const places=NobetService.yerSirali(arr('nobetYerleri')),assign=arr('nobetAtamalari'),chiefs=arr('nobetciAmirleri'),holidays=arr('resmiTatiller'),days=new Date(dutyYear,dutyMonth+1,0).getDate(),rows=[];for(let d=1;d<=days;d++){const iso=NobetService.tarihISO(dutyYear,dutyMonth,d),dt=new Date(dutyYear,dutyMonth,d),weekend=[0,6].includes(dt.getDay()),holiday=holidays.find(t=>t.tarih===iso),dayName=dt.toLocaleDateString('tr-TR',{weekday:'short'});if(weekend)rows.push(`<tr class="ka-duty-grid__weekend"><th><b>${d}</b><small>${esc(dayName)}</small></th><td colspan="${places.length+1}">Hafta sonu</td></tr>`);else if(holiday)rows.push(`<tr class="ka-duty-grid__holiday"><th><b>${d}</b><small>${esc(dayName)}</small></th><td colspan="${places.length+1}">🎉 ${esc(holiday.aciklama||'Resmi Tatil')}</td></tr>`);else{const cells=places.map(p=>{const a=assign.find(x=>x.tarih===iso&&x.yerId===p.id);return`<td><button type="button" class="ka-duty-cell ${a?'filled':''}" data-duty-cell="${iso}" data-duty-place="${esc(p.id)}" ${canEditDuty()?'':'disabled'}>${a?`<strong>${esc(a.ogretmenAdSoyad||'')}</strong>`:'<span>＋</span>'}</button></td>`}).join(''),c=chiefs.find(x=>x.tarih===iso);rows.push(`<tr><th><b>${d}</b><small>${esc(dayName)}</small></th>${cells}<td><button type="button" class="ka-duty-cell ${c?'filled':''}" data-duty-chief="${iso}" ${canEditDuty()?'':'disabled'}>${c?`<strong>${esc(c.ad||'')}</strong>`:'<span>＋</span>'}</button></td></tr>`)}}return`<div class="ka-table-wrap ka-duty-grid-wrap"><table class="ka-duty-grid"><thead><tr><th>Tarih</th>${places.map(p=>`<th>${esc(p.ad||'Nöbet Yeri')}</th>`).join('')}<th>Nöbetçi Amir</th></tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
